37	    fn single_duplicate() {
38	        let mut arr = [1, 3, 3, 4];
39	        assert_eq!(throttle_function(&mut arr), vec![3]);
40	        assert_eq!(arr, [1, 3, 3, 4]);
41	    }
42	
