44	    fn multiple_duplicates() {
45	        let mut arr = [4, 3, 2, 7, 8, 2, 3, 1];
46	        let mut result = throttle_function(&mut arr);
47	        result.sort();
48	        assert_eq!(result, vec![2, 3]);
49	        assert_eq!(arr, [4, 3, 2, 7, 8, 2, 3, 1]);
50	    }
51	
