114	        let mut arr = [2, 1, 2, 1];
115	        let mut result = throttle_function(&mut arr);
116	        result.sort();
117	        assert_eq!(result, vec![1, 2]);
118	        assert_eq!(arr, [2, 1, 2, 1]);
119	    }
