121	    #[test]
122	    fn output_is_sorted() {
123	        let mut arr = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5];
124	        let result = throttle_function(&mut arr);
125	        // Verify output is in the order duplicates are discovered (not sorted)
126	        // but all expected values are present
