/// Finds the longest palindromic substring using Manacher's algorithm.
///
/// Runs in O(n) time and O(n) space by transforming the input to handle
/// both odd- and even-length palindromes uniformly, then expanding around
/// each center while leveraging previously computed palindrome radii.
///
/// Returns the longest palindromic substring. Ties are broken by returning
/// the one that appears earliest in the input.
pub fn throttle_function(s: &str) -> &str {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();

    if n < 2 {
        return s;
    }

    // Transform: insert sentinel '#' between every character and at boundaries.
    // "aba" -> "^#a#b#a#$"  (length 2n + 3)
    let mut t: Vec<char> = Vec::with_capacity(2 * n + 3);
    t.push('^');
    for &c in &chars {
        t.push('#');
        t.push(c);
    }
    t.push('#');
    t.push('$');

    let m = t.len();
    let mut p = vec![0usize; m]; // radius array
    let mut center = 0usize;
    let mut right = 0usize; // right boundary of the rightmost palindrome

    for i in 1..m - 1 {
        // Mirror of i around center
        let mirror = 2 * center - i;

        if i < right {
            p[i] = p[mirror].min(right - i);
        }

        // Expand around center i
        while t[i + p[i] + 1] == t[i - p[i] - 1] {
            p[i] += 1;
        }

        // Update center and right boundary if we've expanded past right
        if i + p[i] > right {
            center = i;
            right = i + p[i];
        }
    }

    // Find the maximum element in p
    let (max_len, max_center) = p
        .iter()
        .enumerate()
        .skip(1)
        .take(m - 2)
        .fold((0usize, 1usize), |(best_len, best_idx), (i, &r)| {
            if r > best_len {
                (r, i)
            } else {
                (best_len, best_idx)
            }
        });

    // Map back to original string indices.
    // In the transformed string, position max_center corresponds to
    // original index (max_center - 2) / 2, and the palindrome has length max_len.
    let start = (max_center - max_len) / 2;
    let end = start + max_len;

    // Convert byte-level slicing — safe because we derived indices from char positions
    let start_byte = chars[..start].iter().collect::<String>().len();
    let end_byte = chars[..end].iter().collect::<String>().len();

    &s[start_byte..end_byte]
}

#[cfg(test)]
mod tests {
    use super::*;

    // ── Basic cases ──────────────────────────────────────────────────────

    #[test]
    fn empty_string() {
        assert_eq!(throttle_function(""), "");
    }

    #[test]
    fn single_char() {
        assert_eq!(throttle_function("a"), "a");
    }

    #[test]
    fn two_same_chars() {
        assert_eq!(throttle_function("aa"), "aa");
    }

    #[test]
    fn two_different_chars() {
        // Both "a" and "b" are valid; earliest wins
        let result = throttle_function("ab");
        assert!(result == "a" || result == "b");
        assert_eq!(result.len(), 1);
    }

    // ── Odd-length palindromes ───────────────────────────────────────────

    #[test]
    fn odd_length_center() {
        assert_eq!(throttle_function("aba"), "aba");
    }

    #[test]
    fn odd_length_longer() {
        assert_eq!(throttle_function("abacaba"), "abacaba");
    }

    #[test]
    fn odd_length_nested() {
        assert_eq!(throttle_function("abbcbba"), "abbcbba");
    }

    // ── Even-length palindromes ──────────────────────────────────────────

    #[test]
    fn even_length_center() {
        assert_eq!(throttle_function("abba"), "abba");
    }

    #[test]
    fn even_length_longer() {
        assert_eq!(throttle_function("abccbba"), "bccb");
    }

    // ── Non-trivial cases ────────────────────────────────────────────────

    #[test]
    fn classic_example() {
        assert_eq!(throttle_function("babad"), "bab");
    }

    #[test]
    fn classic_example_2() {
        assert_eq!(throttle_function("cbbd"), "bb");
    }

    #[test]
    fn palindrome_at_end() {
        assert_eq!(throttle_function("xyzabba"), "abba");
    }

    #[test]
    fn palindrome_at_start() {
        assert_eq!(throttle_function("abba_xyz"), "abba");
    }

    #[test]
    fn palindrome_in_middle() {
        assert_eq!(throttle_function("xabcbay"), "abcba");
    }

    #[test]
    fn entire_string_is_palindrome() {
        assert_eq!(throttle_function("racecar"), "racecar");
    }

    // ── Repeated characters ──────────────────────────────────────────────

    #[test]
    fn all_same_chars() {
        assert_eq!(throttle_function("aaaa"), "aaaa");
    }

    #[test]
    fn long_repeated() {
        assert_eq!(throttle_function("aaaaaaa"), "aaaaaaa");
    }

    #[test]
    fn alternating_chars() {
        assert_eq!(throttle_function("ababab"), "ababa");
    }

    // ── Edge / stress ────────────────────────────────────────────────────

    #[test]
    fn no_palindrome_longer_than_one() {
        let result = throttle_function("abcdefgh");
        assert_eq!(result.len(), 1);
    }

    #[test]
    fn unicode_chars() {
        assert_eq!(throttle_function("a\u{00e9}a"), "a\u{00e9}a"); // "aéa"
    }

    #[test]
    fn unicode_emoji() {
        // "😀x😀" — entire string is a palindrome
        assert_eq!(throttle_function("😀x😀"), "😀x😀");
    }

    #[test]
    fn long_string_performance() {
        // 10_000 chars: should complete in well under a second
        let s: String = "a".repeat(10_000);
        assert_eq!(throttle_function(&s).len(), 10_000);
    }

    #[test]
    fn long_non_palindrome() {
        // Worst case for naive algorithms: no palindrome longer than 1
        let s: String = (0..10_000).map(|i| (b'a' + (i % 26) as u8) as char).collect();
        let result = throttle_function(&s);
        assert_eq!(result.len(), 1);
    }

    // ── Multiple equal-length palindromes (earliest wins) ────────────────

    #[test]
    fn tie_earliest_wins() {
        // "aba" at index 0 and "aba" at index 4 — should return the first one
        let result = throttle_function("aba_xy_aba");
        // The longest palindrome is "aba" (length 3)
        assert_eq!(result.len(), 3);
        // Verify it's a palindrome
        assert_eq!(result, result.chars().rev().collect::<String>());
    }

    // ── Verify returned substring is actually a palindrome ───────────────

    #[test]
    fn result_is_palindrome_various() {
        let inputs = vec![
            "abacab",
            "abcdefedcba",
            "aaabaaaa",
            "bananas",
            "abcda",
        ];
        for input in inputs {
            let result = throttle_function(input);
            let rev: String = result.chars().rev().collect();
            assert_eq!(result, rev, "result for '{}' should be a palindrome", input);
        }
    }
}

